"logo_url":null,"firm_size_fit":[]},"listing":{"slug":"courtlistener-mcp","name":"CourtListener MCP (Free Law Project)","tagline":"Official CourtListener access for case law, dockets, judges, citations and alerts.","description":"Free Law Project hosts the official CourtListener MCP server. Its documentation describes searching U.S. case law, dockets, judges and oral arguments, citation tools and alert management. Interactive clients use a CourtListener account with OAuth; the maintainer also documents API-token authentication for other clients. Some tools can change account state or request documents, so inspect permissions and possible charges. Documentation reviewed; an account connection was not tested.","category":"legal_research","external_url":"https://mcp.courtlistener.com/","mcp_repo_url":"https://github.com/freelawproject/courtlistener-api-client","mcp_install_command":null,"pricing_model":"freemium","pricing_details":"The maintainer documents free individual accounts. Usage limits, memberships, document purchases and other charges depend on the service and account; confirm current terms.","tags":["case-law","dockets","citations","alerts","official","mcp"],"creator_name":"Free Law Project","creator_url":"https://free.law","logo_url":null,"firm_size_fit":[],"status":"published"},"review":{"slug":"courtlistener-mcp","decision":"approved","reviewed_at":"2026-10-27","reviewer":"Codex primary-source catalog audit, independently integrated","identity_confirmed":true,"capabilities_confirmed":true,"mcp_confirmed":true,"sources":[{"url":"https://raw.githubusercontent.com/freelawproject/courtlistener-api-client/main/MCP_README.md","kind":"maintainer","sha256":"ce8ed226f549546b22708eccd2e7422e11d00ec87c0afeac3ae53e74d6e0611c","quote":"Search U.S. case law, dockets, judges, and oral arguments; extract and verify legal citations; and manage alerts"}],"listing_sha256":"6558ecf9db1c09a83a4359ab215f39792603d8a9dd28516db52c55261c165512","claims":{"slug":"courtlistener-mcp","name":"CourtListener MCP (Free Law Project)","tagline":"Official CourtListener access for case law, dockets, judges, citations and alerts.","description":"Free Law Project hosts the official CourtListener MCP server. Its documentation describes searching U.S. case law, dockets, judges and oral arguments, citation tools and alert management. Interactive clients use a CourtListener account with OAuth; the maintainer also documents API-token authentication for other clients. Some tools can change account state or request documents, so inspect permissions and possible charges. Documentation reviewed; an account connection was not tested.","category":"legal_research","external_url":"https://mcp.courtlistener.com/","mcp_repo_url":"https://github.com/freelawproject/courtlistener-api-client","mcp_install_command":null,"pricing_model":"freemium","pricing_details":"The maintainer documents free individual accounts. Usage limits, memberships, document purchases and other charges depend on the service and account; confirm current terms.","tags":["case-law","dockets","citations","alerts","official","mcp"],"creator_name":"Free Law Project","creator_url":"https://free.law","logo_url":null,"firm_size_fit":[]}}}]$catalog_6884eeb32d64c205$::jsonb) loop
    select * into previous from legalaimcp.listings where id=(item->>'id')::uuid for update;
    if not found or previous.status::text is distinct from item->>'expected_status' or legalaimcp.catalog_claims(to_jsonb(previous)) <> item->'expected_claims' then
      raise exception 'Catalog changed since inspection; whole import refused';
    end if;
    replacement := jsonb_populate_record(null::legalaimcp.listings,item->'listing');
    if replacement.status='published' then
      insert into legalaimcp.catalog_reviews(slug,claims,reviewer,reviewed_at,evidence)
      values(replacement.slug,legalaimcp.catalog_claims(item->'listing'),item->'review'->>'reviewer',(item->'review'->>'reviewed_at')::date,item->'review')
      on conflict(slug) do update set claims=excluded.claims,reviewer=excluded.reviewer,reviewed_at=excluded.reviewed_at,evidence=excluded.evidence,updated_at=now();
    end if;
    update legalaimcp.listings set
      name=replacement.name,tagline=replacement.tagline,description=replacement.description,category=replacement.category,
      external_url=replacement.external_url,mcp_repo_url=replacement.mcp_repo_url,mcp_install_command=replacement.mcp_install_command,
      pricing_model=replacement.pricing_model,pricing_details=replacement.pricing_details,tags=replacement.tags,
      creator_name=replacement.creator_name,creator_url=replacement.creator_url,logo_url=replacement.logo_url,firm_size_fit=replacement.firm_size_fit,
      status=replacement.status,verified=false,verified_at=null
    where id=previous.id;
  end loop;
end;
